mkitem!{# [doc = " A macro for triggering an ICE."] # [doc = " Calling `bug` instead of panicking will result in a nicer error message and should"] # [doc = " therefore be preferred over `panic`/`unreachable` or others."] # [doc = ""] # [doc = " If you have a span available, you should use [`span_bug`] instead."] # [doc = ""] # [doc = " If the bug should only be emitted when compilation didn't fail,"] # [doc = " [`DiagCtxtHandle::span_delayed_bug`] may be useful."] # [doc = ""] # [doc = " [`DiagCtxtHandle::span_delayed_bug`]: rustc_errors::DiagCtxtHandle::span_delayed_bug"] # [doc = " [`span_bug`]: crate::span_bug"] # [macro_export] macro_rules ! bug { () => ($ crate :: bug ! ("impossible case reached")) ; ($ ($ arg : tt) +) => ($ crate :: util :: bug :: bug_fmt (:: std :: format_args ! ($ ($ arg) +))) ; }}
mkitem!{# [doc = " A macro for triggering an ICE with a span."] # [doc = " Calling `span_bug!` instead of panicking will result in a nicer error message and point"] # [doc = " at the code the compiler was compiling when it ICEd. This is the preferred way to trigger"] # [doc = " ICEs."] # [doc = ""] # [doc = " If the bug should only be emitted when compilation didn't fail,"] # [doc = " [`DiagCtxtHandle::span_delayed_bug`] may be useful."] # [doc = ""] # [doc = " [`DiagCtxtHandle::span_delayed_bug`]: rustc_errors::DiagCtxtHandle::span_delayed_bug"] # [macro_export] macro_rules ! span_bug { ($ span : expr , $ ($ arg : tt) +) => ($ crate :: util :: bug :: span_bug_fmt ($ span , :: std :: format_args ! ($ ($ arg) +))) ; }}
mkitem!{macro_rules ! TrivialLiftImpls { ($ ($ ty : ty) ,+ $ (,) ?) => { $ (impl <'tcx > $ crate :: ty :: Lift <$ crate :: ty :: TyCtxt <'tcx >> for $ ty { type Lifted = Self ; fn lift_to_interner (self , _ : $ crate :: ty :: TyCtxt <'tcx >) -> Option < Self > { Some (self) } }) + } ; }}
mkitem!{# [doc = " Used for types that are `Copy` and which **do not care about arena"] # [doc = " allocated data** (i.e., don't need to be folded)."] macro_rules ! TrivialTypeTraversalImpls { ($ ($ ty : ty) ,+ $ (,) ?) => { $ (impl <'tcx > $ crate :: ty :: TypeFoldable <$ crate :: ty :: TyCtxt <'tcx >> for $ ty { fn try_fold_with < F : $ crate :: ty :: FallibleTypeFolder <$ crate :: ty :: TyCtxt <'tcx >>> (self , _ : & mut F ,) -> :: std :: result :: Result < Self , F :: Error > { Ok (self) } # [inline] fn fold_with < F : $ crate :: ty :: TypeFolder <$ crate :: ty :: TyCtxt <'tcx >>> (self , _ : & mut F ,) -> Self { self } } impl <'tcx > $ crate :: ty :: TypeVisitable <$ crate :: ty :: TyCtxt <'tcx >> for $ ty { # [inline] fn visit_with < F : $ crate :: ty :: TypeVisitor <$ crate :: ty :: TyCtxt <'tcx >>> (& self , _ : & mut F) -> F :: Result { < F :: Result as :: rustc_middle :: ty :: VisitorResult >:: output () } }) + } ; }}
mkitem!{macro_rules ! TrivialTypeTraversalAndLiftImpls { ($ ($ t : tt) *) => { TrivialTypeTraversalImpls ! { $ ($ t) * } TrivialLiftImpls ! { $ ($ t) * } } }}